SELECT
WHERE c.deleted = 0 AND c.audit_status = 1
AND c.category_id = #{q.categoryId}
AND c.craftsman_id = #{q.craftsmanId}
AND c.status = #{q.status}
AND (c.title LIKE CONCAT('%', #{q.keyword}, '%') OR c.subtitle LIKE CONCAT('%', #{q.keyword}, '%'))
AND c.status = 0 AND c.remain_quota > 0 AND (c.booking_deadline IS NULL OR c.booking_deadline > NOW())
ORDER BY c.price ASC, c.id DESC ORDER BY c.price DESC, c.id DESC ORDER BY c.booking_count DESC, c.view_count DESC, c.id DESC ORDER BY c.start_time ASC, c.id DESC ORDER BY c.status ASC, c.start_time ASC, c.id DESC

SELECT


WHERE c.deleted = 0 AND c.craftsman_id = #{craftsmanId}

    AND c.status = #{q.status}


    AND (c.title LIKE CONCAT('%', #{q.keyword}, '%')
         OR c.subtitle LIKE CONCAT('%', #{q.keyword}, '%'))

ORDER BY c.status ASC, c.start_time DESC, c.id DESC

SELECT


WHERE c.deleted = 0
AND c.craftsman_id = #{craftsmanId}
AND c.start_time >= #{start}
AND c.start_time < #{end}
ORDER BY c.start_time ASC, c.id ASC

SELECT
,
c.audit_status  AS auditStatus,
c.reject_reason AS rejectReason,
c.create_time   AS createTime,
c.update_time   AS updateTime

WHERE c.deleted = 0

    AND c.status = #{q.status}


    AND c.audit_status = #{q.auditStatus}


    AND c.category_id = #{q.categoryId}


    AND c.craftsman_id = #{q.craftsmanId}


    AND (c.title LIKE CONCAT('%', #{q.keyword}, '%')
    OR c.subtitle LIKE CONCAT('%', #{q.keyword}, '%')
    OR cr.real_name LIKE CONCAT('%', #{q.keyword}, '%'))


    AND c.start_time >= #{q.startTime}


    AND c.start_time <= #{q.endTime}


    ORDER BY c.start_time ASC, c.id DESC
    ORDER BY c.booking_count DESC, c.view_count DESC, c.id DESC

    ORDER BY (c.remain_quota / c.total_quota) ASC, c.id DESC
    ORDER BY c.create_time DESC, c.id DESC
